function StatusPill({ children, tone = 'default' }: { children: ReactNode; tone?: 'default' | 'green' | 'amber' | 'red' | 'blue' }) {
  const tones = { default: 'bg-mist text-ink-soft', green: 'bg-green-100 text-green-800', amber: 'bg-lumen/30 text-ink', red: 'bg-red-100 text-red-800', blue: 'bg-sky-100 text-sky-800' };
  return <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-bold uppercase tracking-[0.12em] ${tones[tone]}`}>{children}</span>;
}

function Button({ children, variant = 'primary', className = '', ...props }: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'quiet' | 'outline' | 'danger' }) {
  const styles = {
    primary: 'bg-teal text-sand shadow-[0_5px_0_hsl(198_35%_18%/.14)] hover:-translate-y-0.5 hover:shadow-[0_7px_0_hsl(198_35%_18%/.14)]',
    quiet: 'bg-mist text-ink hover:bg-mist-deep',
    outline: 'border border-line bg-card text-ink hover:border-teal hover:text-teal',
    danger: 'bg-red-700 text-sand hover:bg-red-800',
  };
  return <button className={`inline-flex min-h-10 items-center justify-center gap-2 rounded-xl px-4 py-2 text-sm font-bold transition-all duration-200 disabled:cursor-not-allowed disabled:opacity-50 ${styles[variant]} ${className}`} {...props}>{children}</button>;
}

function Field({ label, name, type = 'text', placeholder, required, value, onChange }: { label: string; name: string; type?: string; placeholder?: string; required?: boolean; value?: string; onChange?: (e: ChangeEvent<HTMLInputElement>) => void }) {
  return <label className="grid gap-2 text-sm font-bold text-ink" htmlFor={name}>{label}{required && <span className="ml-1 text-coral">*</span>}
    <input id={name} name={name} type={type} placeholder={placeholder} required={required} value={value} onChange={onChange} className="h-11 rounded-xl border border-line bg-card px-3.5 font-normal outline-none transition focus:border-teal focus:ring-4 focus:ring-teal/10" data-testid={`input-${name}`} />
  </label>;
}

