function HowItWorksPage() {
  const steps = [
    { number: '01', title: 'Report with useful context', body: 'A guided form captures the category, place, date, description, optional photo, and private identifying marks. Duplicate-looking reports are flagged before you publish.', icon: FileText },
    { number: '02', title: 'Match with explainable signals', body: 'A local rule-based scorer compares opposite report types using category, color, brand, campus location, date, and meaningful keywords. Every score includes the reason it was suggested.', icon: Sparkles },
    { number: '03', title: 'Verify privately', body: 'The public directory never exposes sensitive ownership details. A claimant supplies private proof, the reporter reviews it, and both sides can keep the conversation inside the secure inbox.', icon: LockKeyhole },
    { number: '04', title: 'Return with a checkpoint', body: 'Approved claims move to the security queue. A one-time handover code confirms the in-person exchange and closes the report as returned.', icon: ShieldCheck },
  ];
  return <div className="mx-auto max-w-5xl"><PageHeader eyebrow="Judge-ready overview" title="How Campus Pick works" body="A simple recovery workflow backed by persistent data, role-aware screens, and a transparent matching engine." action={<Link href="/dashboard" className="inline-flex items-center gap-2 rounded-xl bg-teal px-4 py-2.5 text-sm font-bold text-sand" data-testid="link-how-dashboard">Open demo workspace <ArrowRight size={16} /></Link>} /><div className="grid gap-4 md:grid-cols-2">{steps.map(({ number, title, body, icon: Icon }) => <article key={number} className="rounded-2xl border border-line bg-card p-6"><div className="flex items-start justify-between"><span className="font-mono text-xs font-bold text-coral">{number}</span><span className="grid h-10 w-10 place-items-center rounded-xl bg-mist text-teal"><Icon size={19} /></span></div><h2 className="mt-8 font-display text-xl font-bold">{title}</h2><p className="mt-2 text-sm leading-6 text-ink-muted">{body}</p></article>)}</div><section className="mt-8 rounded-2xl bg-ink p-6 text-sand md:p-8"><div className="flex flex-col gap-7 md:flex-row md:items-start md:justify-between"><div><p className="font-mono text-xs uppercase tracking-[.16em] text-lumen">Technical notes</p><h2 className="mt-3 font-display text-2xl font-bold">Built to grow without locking in paid AI.</h2><p className="mt-3 max-w-2xl text-sm leading-7 text-sand/65">The current matcher is deterministic, fast, and easy to explain during a handoff. Because reports and match reasons are stored in Postgres, a future embedding or image model can be added as another scoring signal without changing the privacy or verification workflow.</p></div><div className="grid shrink-0 gap-2 text-sm md:w-64"><div className="rounded-xl border border-white/10 bg-white/5 px-4 py-3"><span className="text-lumen">Database</span><span className="ml-2 text-sand/70">Postgres + Drizzle</span></div><div className="rounded-xl border border-white/10 bg-white/5 px-4 py-3"><span className="text-lumen">Auth</span><span className="ml-2 text-sand/70">Managed Clerk</span></div><div className="rounded-xl border border-white/10 bg-white/5 px-4 py-3"><span className="text-lumen">Access</span><span className="ml-2 text-sand/70">Role-aware queues</span></div></div></div></section></div>;
}

function ItemCard({ item, onSave, onOpen }: { item: Item; onSave?: () => void; onOpen?: () => void }) {
  return <article className="group overflow-hidden rounded-2xl border border-line bg-card transition hover:-translate-y-0.5 hover:border-teal/50 hover:shadow-lg hover:shadow-ink/5" data-testid={`card-item-${item.id}`}><div className="relative flex h-36 items-center justify-center bg-mist">{item.imageUrl ? <img src={item.imageUrl} alt={item.itemName} className="h-full w-full object-cover" /> : <span className="grid h-16 w-16 place-items-center rounded-2xl bg-card text-teal shadow-sm"><PackageCheck size={28} /></span>}<span className="absolute left-3 top-3"><StatusPill tone={item.type === 'lost' ? 'red' : 'green'}>{item.type}</StatusPill></span><button className="absolute right-3 top-3 grid h-8 w-8 place-items-center rounded-full bg-card/90 text-ink-muted transition hover:text-coral" onClick={onSave} aria-label={item.isSaved ? 'Unsave item' : 'Save item'} data-testid={`button-save-item-${item.id}`}><Heart size={16} fill={item.isSaved ? 'currentColor' : 'none'} /></button></div><button className="block w-full p-4 text-left" onClick={onOpen} data-testid={`button-open-item-${item.id}`}><div className="flex items-start justify-between gap-3"><div><p className="font-display font-bold text-ink">{item.itemName}</p><p className="mt-1 text-xs text-ink-muted">{item.brand || item.category}{item.color ? ` · ${item.color}` : ''}</p></div>{item.matchScore && <span className="font-mono text-xs font-bold text-teal">{item.matchScore}%</span>}</div><div className="mt-4 flex items-center gap-2 text-xs text-ink-muted"><MapPin size={13} className="text-coral" /> {item.location}</div><div className="mt-2 flex items-center gap-2 text-xs text-ink-muted"><Clock3 size={13} /> {item.eventDate}</div></button></article>;
}

function DashboardPage() {
  const query = useGetDashboard();
  const dashboard = query.data;
  if (query.isLoading) return <><PageHeader eyebrow="Workspace" title="Your recovery desk" /><LoadingRows /></>;
  if (query.isError || !dashboard) return <><PageHeader eyebrow="Workspace" title="Your recovery desk" /><ErrorState retry={() => query.refetch()} /></>;
  const stats = [
    { label: 'My reports', value: dashboard.stats.myReports, Icon: FileText, tone: 'text-teal' },
    { label: 'Potential matches', value: dashboard.stats.potentialMatches, Icon: Sparkles, tone: 'text-coral' },
    { label: 'Active claims', value: dashboard.stats.activeClaims, Icon: ClipboardCheck, tone: 'text-amber-700' },
    { label: 'Returned items', value: dashboard.stats.returnedItems, Icon: PackageCheck, tone: 'text-teal' },
  ];
  return <><PageHeader eyebrow={`${dashboard.role || 'Student'} account`} title={`Good morning, ${dashboard.userName || 'Jordan'}.`} body="Here’s the latest movement on your reports and the items you’re watching." action={<Link href="/report/lost" className="inline-flex items-center gap-2 rounded-xl bg-teal px-4 py-2.5 text-sm font-bold text-sand" data-testid="link-dashboard-new-report"><Plus size={17} /> New report</Link>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{stats.map(({ label, value, Icon, tone }) => <div key={label} className="rounded-2xl border border-line bg-card p-5"><div className="flex items-center justify-between"><p className="text-sm text-ink-muted">{label}</p><Icon size={18} className={tone} /></div><p className="mt-5 font-display text-4xl font-bold text-ink">{value}</p><p className="mt-1 text-xs text-ink-muted">Updated just now</p></div>)}</div><div className="mt-8 grid gap-6 xl:grid-cols-[1.2fr_.8fr]"><section><div className="mb-4 flex items-center justify-between"><h2 className="font-display text-xl font-bold">Recent reports</h2><Link href="/find" className="text-sm font-bold text-teal hover:underline" data-testid="link-dashboard-view-all">View all</Link></div>{dashboard.recentItems?.length ? <div className="grid gap-4 sm:grid-cols-2">{dashboard.recentItems.slice(0, 4).map((item) => <ItemCard key={item.id} item={item} />)}</div> : <EmptyState icon={FileText} title="Your first report starts here" body="Tell the campus what you’re looking for, or help someone by reporting an item you found." action={<Link href="/report/lost" className="text-sm font-bold text-teal" data-testid="link-dashboard-empty-report">Create a report</Link>} />}</section><section className="rounded-2xl border border-line bg-card p-5"><div className="flex items-center justify-between"><h2 className="font-display text-xl font-bold">Activity</h2><span className="font-mono text-[10px] uppercase tracking-widest text-ink-muted">Live</span></div><div className="mt-5 space-y-5">{dashboard.recentActivity?.length ? dashboard.recentActivity.slice(0, 5).map((activity) => <div key={activity.id} className="flex gap-3"><span className="mt-1 h-2 w-2 shrink-0 rounded-full bg-lumen ring-4 ring-lumen/20" /><div><p className="text-sm font-bold text-ink">{activity.title}</p><p className="mt-1 text-xs leading-5 text-ink-muted">{activity.description}</p><p className="mt-1 font-mono text-[10px] text-ink-muted">{activity.time}</p></div></div>) : <p className="py-8 text-sm text-ink-muted">Your recent activity will appear here.</p>}</div></section></div></>;
}

function FindPage() {
  const [search, setSearch] = useState('');
  const [type, setType] = useState<'all' | 'lost' | 'found'>('all');
  const [, setLocation] = useLocation();
  const params = useMemo<ListItemsParams>(() => ({ q: search || undefined, type, sort: search ? 'relevance' : 'newest' }), [search, type]);
  const query = useListItems(params);
  const save = useToggleSavedItem();
  const items = query.data?.items || [];
  return <><PageHeader eyebrow="Campus directory" title="Find an item" body="Search recent lost and found reports across campus. Owners keep identifying details private until they’re ready to verify." action={<div className="flex gap-2"><Link href="/report/lost" className="rounded-xl border border-line bg-card px-3 py-2.5 text-sm font-bold text-ink" data-testid="link-find-report-lost">Lost something?</Link><Link href="/report/found" className="rounded-xl bg-teal px-3 py-2.5 text-sm font-bold text-sand" data-testid="link-find-report-found">Found something?</Link></div>} /><div className="mb-6 flex flex-col gap-3 sm:flex-row"><label className="relative flex-1"><Search size={18} className="absolute left-3.5 top-3.5 text-ink-muted" /><input value={search} onChange={(e) => setSearch(e.target.value)} className="h-12 w-full rounded-xl border border-line bg-card pl-11 pr-4 text-sm outline-none focus:border-teal focus:ring-4 focus:ring-teal/10" placeholder="Search by item, brand, or place..." data-testid="input-search-items" /></label><div className="flex rounded-xl border border-line bg-card p-1" data-testid="filter-item-type">{(['all', 'lost', 'found'] as const).map((value) => <button key={value} onClick={() => setType(value)} className={`rounded-lg px-4 py-2 text-sm font-bold capitalize ${type === value ? 'bg-ink text-sand' : 'text-ink-muted hover:text-ink'}`} data-testid={`button-filter-${value}`}>{value}</button>)}</div><button className="grid h-12 w-12 place-items-center rounded-xl border border-line bg-card text-ink-muted hover:text-teal" aria-label="More filters" data-testid="button-more-filters"><ListFilter size={18} /></button></div>{query.isLoading ? <LoadingRows count={6} /> : query.isError ? <ErrorState retry={() => query.refetch()} /> : items.length ? <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{items.map((item) => <ItemCard key={item.id} item={item} onSave={() => save.mutate({ id: item.id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListItemsQueryKey(params) }) })} onOpen={() => setLocation(`/find/${item.id}`)} />)}</div> : <EmptyState icon={Search} title="No reports match that search" body="Try a broader term, a different location, or check back soon. New reports appear throughout the day." action={<Button variant="quiet" onClick={() => { setSearch(''); setType('all'); }} data-testid="button-clear-search">Clear search</Button>} />}</>;
}

function ReportPage({ type }: { type: 'lost' | 'found' }) {
  const [, setLocation] = useLocation();
  const create = useCreateItem();
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState('');
  const [imageError, setImageError] = useState('');
  const [imageUrl, setImageUrl] = useState('');
  const [duplicateHint, setDuplicateHint] = useState('');
  const [reportName, setReportName] = useState('');
  const [reportLocation, setReportLocation] = useState('');
  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); setError('');
    if (imageError) {
      setError(imageError);
      return;
    }
    const form = new FormData(event.currentTarget);
    const data: ItemInput = { type, itemName: String(form.get('itemName')), category: String(form.get('category')), description: String(form.get('description')), brand: String(form.get('brand') || '') || null, model: String(form.get('model') || '') || null, color: String(form.get('color') || '') || null, location: String(form.get('location')), eventDate: String(form.get('eventDate')), approximateTime: String(form.get('approximateTime') || '') || null, condition: String(form.get('condition') || '') || null, identifyingFeatures: String(form.get('identifyingFeatures') || '') || null, storageStatus: type === 'found' ? String(form.get('storageStatus') || '') || null : null, imageUrl: imageUrl || null };
    create.mutate({ data }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getListItemsQueryKey() }); queryClient.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); setSubmitted(true); }, onError: () => setError('We couldn’t save this report. Please review the details and try again.') });
  }
  if (submitted) return <div className="mx-auto max-w-xl py-10 text-center"><span className="mx-auto grid h-16 w-16 place-items-center rounded-2xl bg-lumen text-ink"><Check size={30} /></span><p className="mt-6 font-mono text-xs uppercase tracking-[.16em] text-teal">Report received</p><h1 className="mt-3 font-display text-4xl font-bold tracking-tight">You’ve done the helpful thing.</h1><p className="mt-4 text-ink-muted">Your report is now visible to the campus recovery desk. We’ll let you know if a potential match turns up.</p><div className="mt-8 flex justify-center gap-3"><Link href="/dashboard" className="rounded-xl bg-teal px-4 py-3 text-sm font-bold text-sand" data-testid="link-report-success-dashboard">Back to overview</Link><Link href="/find" className="rounded-xl border border-line bg-card px-4 py-3 text-sm font-bold text-ink" data-testid="link-report-success-find">Browse reports</Link></div></div>;
   return <div className="mx-auto max-w-3xl"><PageHeader eyebrow={type === 'lost' ? 'Start a recovery' : 'Help someone out'} title={type === 'lost' ? 'Report something lost' : 'Report something found'} body={type === 'lost' ? 'Give us the details you remember. The more specific, the better we can connect the dots.' : 'A few clear details can reunite an item with its owner. Please don’t include private contact information.'} /><form onSubmit={submit} className="space-y-7 rounded-2xl border border-line bg-card p-5 md:p-8" data-testid={`form-report-${type}`}><div className="grid gap-5 sm:grid-cols-2"><label className="grid gap-2 text-sm font-bold text-ink" htmlFor="itemName">What is it?<input id="itemName" name="itemName" placeholder="e.g. Navy canvas backpack" required value={reportName} onChange={(event) => { setReportName(event.target.value); setDuplicateHint(event.target.value.length > 3 ? 'We’ll compare this report with existing campus reports before publishing.' : ''); }} className="h-11 rounded-xl border border-line bg-card px-3.5 font-normal outline-none transition focus:border-teal focus:ring-4 focus:ring-teal/10" data-testid="input-itemName" /></label><label className="grid gap-2 text-sm font-bold text-ink">Category<span><select name="category" required className="h-11 w-full rounded-xl border border-line bg-card px-3.5 font-normal outline-none focus:border-teal" data-testid="select-category"><option value="">Choose one</option><option>Bag</option><option>Electronics</option><option>Clothing</option><option>Keys</option><option>Books</option><option>Cards and ID</option><option>Other</option></select></span></label></div>{duplicateHint && <div className="flex items-start gap-3 rounded-xl border border-lumen/60 bg-lumen/15 p-3 text-sm text-ink" data-testid="duplicate-check-hint"><Search size={17} className="mt-0.5 shrink-0 text-teal" /><span><strong>Duplicate check enabled.</strong> {duplicateHint}</span></div>}<label className="grid gap-2 text-sm font-bold text-ink">What should we know?<textarea name="description" required minLength={10} rows={4} placeholder="Describe what it looks like and what happened..." className="rounded-xl border border-line bg-card p-3.5 font-normal outline-none focus:border-teal focus:ring-4 focus:ring-teal/10" data-testid="input-description" /></label><div className="grid gap-5 sm:grid-cols-3"><Field label="Brand" name="brand" placeholder="e.g. Herschel" /><Field label="Model or style" name="model" placeholder="e.g. Retreat" /><Field label="Color" name="color" placeholder="e.g. Navy" /></div><div className="grid gap-5 sm:grid-cols-2"><label className="grid gap-2 text-sm font-bold text-ink" htmlFor="location">{type === 'lost' ? 'Last seen at' : 'Found at'}<input id="location" name="location" placeholder="e.g. North Library, 2nd floor" required value={reportLocation} onChange={(event) => setReportLocation(event.target.value)} className="h-11 rounded-xl border border-line bg-card px-3.5 font-normal outline-none transition focus:border-teal focus:ring-4 focus:ring-teal/10" data-testid="input-location" /></label><Field label="Date" name="eventDate" type="date" required /></div><div className="grid gap-5 sm:grid-cols-2"><Field label="Approximate time" name="approximateTime" type="time" /><label className="grid gap-2 text-sm font-bold text-ink">Condition<select name="condition" className="h-11 rounded-xl border border-line bg-card px-3.5 font-normal outline-none focus:border-teal" data-testid="select-condition"><option value="">Choose one</option><option>Like new</option><option>Good</option><option>Worn</option><option>Damaged</option></select></label></div><label className="grid gap-2 text-sm font-bold text-ink">Photo <span className="font-normal text-ink-muted">(optional, compressed before saving)</span><span className="flex items-center gap-3 rounded-xl border border-dashed border-line bg-background p-3"><ImagePlus size={20} className="shrink-0 text-teal" /><input type="file" accept="image/*" onChange={(event) => { const file = event.target.files?.[0]; if (!file) return; setImageError(''); setError(''); const reader = new FileReader(); reader.onload = () => { const source = new Image(); source.onload = () => { const scale = Math.min(1, 1200 / Math.max(source.width, source.height)); const canvas = document.createElement('canvas'); canvas.width = Math.max(1, Math.round(source.width * scale)); canvas.height = Math.max(1, Math.round(source.height * scale)); const context = canvas.getContext('2d'); if (!context) { setImageError('This image could not be prepared. Please choose another photo.'); return; } context.drawImage(source, 0, 0, canvas.width, canvas.height); const compressed = canvas.toDataURL('image/jpeg', 0.78); if (compressed.length > 1_200_000) { setImageError('This photo is still too large after compression. Please choose a smaller image.'); return; } setImageUrl(compressed); }; source.onerror = () => setImageError('This image could not be read. Please choose another photo.'); source.src = String(reader.result); }; reader.onerror = () => setImageError('This image could not be read. Please choose another photo.'); reader.readAsDataURL(file); }} className="min-w-0 text-sm font-normal" data-testid="input-report-image" /></span></label>{imageError && <p className="rounded-xl bg-amber-50 p-3 text-sm text-amber-900" data-testid="text-report-image-error">{imageError}</p>}{imageUrl && <div className="relative overflow-hidden rounded-xl border border-line"><img src={imageUrl} alt="Selected report preview" className="h-44 w-full object-cover" /><button type="button" onClick={() => { setImageUrl(''); setImageError(''); }} className="absolute right-3 top-3 rounded-lg bg-card/90 px-3 py-1.5 text-xs font-bold text-ink" data-testid="button-remove-report-image">Remove</button></div>}<label className="grid gap-2 text-sm font-bold text-ink">Identifying features<textarea name="identifyingFeatures" rows={3} placeholder="Marks, stickers, contents, or other details you can verify privately" className="rounded-xl border border-line bg-card p-3.5 font-normal outline-none focus:border-teal" data-testid="input-identifying-features" /></label>{type === 'found' && <label className="grid gap-2 text-sm font-bold text-ink">Storage status<select name="storageStatus" className="h-11 w-full rounded-xl border border-line bg-card px-3.5 font-normal outline-none focus:border-teal" data-testid="select-storage-status"><option value="">Not stored yet</option><option>At security desk</option><option>With me temporarily</option><option>Department office</option></select></label>}{error && <p className="rounded-xl bg-red-50 p-3 text-sm text-red-800" data-testid="text-report-error">{error}</p>}<div className="flex items-center justify-between border-t border-line pt-6"><Link href="/dashboard" className="text-sm font-bold text-ink-muted hover:text-ink" data-testid="link-report-cancel">Cancel</Link><Button type="submit" disabled={create.isPending || !!imageError} data-testid="button-submit-report">{create.isPending ? 'Saving report...' : <>Submit report <ArrowRight size={16} /></>}</Button></div></form></div>;
}

function MatchesPage() {
  const query = useListMatches();
  const matches = query.data || [];
  return <><PageHeader eyebrow="Assisted recovery" title="Potential matches" body="These reports share enough details to be worth a closer look. You stay in control of what happens next." /><div className="mb-6 flex items-center gap-2 rounded-2xl border border-lumen/50 bg-lumen/15 p-4 text-sm text-ink"><Sparkles size={19} className="text-teal" /><span><strong>Matching is a starting point, not a verdict.</strong> Open the report to compare the details you know.</span></div>{query.isLoading ? <LoadingRows /> : query.isError ? <ErrorState retry={() => query.refetch()} /> : matches.length ? <div className="space-y-4">{matches.map((match) => <MatchRow key={match.id} match={match} />)}</div> : <EmptyState icon={Sparkles} title="No potential matches yet" body="When a new report shares meaningful details with yours, it will appear here." action={<Link href="/find" className="text-sm font-bold text-teal" data-testid="link-matches-browse">Browse the directory</Link>} />}</>;
}

function MatchRow({ match }: { match: Match }) {
  return <article className="rounded-2xl border border-line bg-card p-5 md:p-6" data-testid={`row-match-${match.id}`}><div className="flex flex-col gap-5 md:flex-row md:items-center md:justify-between"><div className="flex items-start gap-4"><div className="grid h-12 w-12 shrink-0 place-items-center rounded-xl bg-mist text-teal"><Sparkles size={21} /></div><div><div className="flex flex-wrap items-center gap-2"><h2 className="font-display text-lg font-bold">{match.itemName}</h2><StatusPill tone={match.score >= 80 ? 'green' : 'amber'}>{match.label}</StatusPill></div><p className="mt-1 text-sm text-ink-muted">Possible match with <span className="font-bold text-ink">{match.matchedItemName}</span> · {match.location}</p><p className="mt-3 text-sm leading-6 text-ink-muted">{match.reason}</p></div></div><div className="flex shrink-0 items-center gap-4 md:flex-col md:items-end"><div className="text-right"><span className="font-mono text-2xl font-bold text-teal">{match.score}%</span><p className="text-[10px] uppercase tracking-widest text-ink-muted">match score</p></div><Link href={`/find?item=${match.matchedItemId}`} className="rounded-xl bg-ink px-4 py-2.5 text-sm font-bold text-sand" data-testid={`link-match-review-${match.id}`}>Review report</Link></div></div></article>;
}

function ClaimsPage() {
  const query = useListClaims();
  const createClaim = useCreateClaim();
  const update = useUpdateClaim();
  const [selected, setSelected] = useState<Claim | null>(null);
  const [claimItemId, setClaimItemId] = useState('');
  const [claimDetails, setClaimDetails] = useState('');
  const claims = query.data || [];
  function change(claim: Claim, status: 'under_verification' | 'approved' | 'rejected' | 'manual_review') { update.mutate({ id: claim.id, data: { status } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getListClaimsQueryKey() }); setSelected(null); } }); }
  function submitClaim(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    createClaim.mutate({ data: { itemId: Number(claimItemId), uniqueMarks: 'Private details supplied in form', additionalDetails: claimDetails } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getListClaimsQueryKey() }); setClaimItemId(''); setClaimDetails(''); } });
  }
  return <><PageHeader eyebrow="Ownership verification" title="Claims" body="Review claims connected to your reports. Keep the handoff safe by checking the details only the owner would know." action={<Button onClick={() => document.getElementById('claim-form')?.scrollIntoView({ behavior: 'smooth' })} data-testid="button-start-claim"><Plus size={16} /> Start a claim</Button>} /><form id="claim-form" onSubmit={submitClaim} className="mb-6 grid gap-3 rounded-2xl border border-line bg-card p-5 md:grid-cols-[160px_1fr_auto]" data-testid="form-create-claim"><input value={claimItemId} onChange={(event) => setClaimItemId(event.target.value)} type="number" min="1" placeholder="Item ID" required className="h-11 rounded-xl border border-line bg-background px-3 text-sm outline-none focus:border-teal" data-testid="input-claim-item-id" /><input value={claimDetails} onChange={(event) => setClaimDetails(event.target.value)} minLength={5} placeholder="A detail only the owner would know" required className="h-11 rounded-xl border border-line bg-background px-3 text-sm outline-none focus:border-teal" data-testid="input-claim-details" /><Button type="submit" disabled={createClaim.isPending} data-testid="button-submit-claim">{createClaim.isPending ? 'Submitting...' : 'Submit private claim'}</Button></form>{query.isLoading ? <LoadingRows /> : query.isError ? <ErrorState retry={() => query.refetch()} /> : claims.length ? <div className="grid gap-4">{claims.map((claim) => <article key={claim.id} className="flex flex-col gap-5 rounded-2xl border border-line bg-card p-5 md:flex-row md:items-center md:justify-between" data-testid={`row-claim-${claim.id}`}><div><div className="flex flex-wrap items-center gap-2"><span className="font-mono text-xs text-ink-muted">{claim.reportId}</span><StatusPill tone={claim.status === 'approved' ? 'green' : claim.status === 'rejected' ? 'red' : 'amber'}>{claim.status.replaceAll('_', ' ')}</StatusPill></div><h2 className="mt-2 font-display text-lg font-bold">{claim.itemName}</h2><p className="mt-1 text-sm text-ink-muted">Claimed by {claim.claimantName} · submitted {claim.submittedAt}</p></div><div className="flex items-center gap-5"><div className="text-right"><p className="font-mono text-xl font-bold text-teal">{claim.confidence}%</p><p className="text-[10px] uppercase tracking-widest text-ink-muted">confidence</p></div><Button variant="outline" onClick={() => setSelected(claim)} data-testid={`button-review-claim-${claim.id}`}>Review claim <ArrowRight size={15} /></Button></div></article>)}</div> : <EmptyState icon={ClipboardCheck} title="No claims to review" body="Claims connected to your reports will appear here when someone requests ownership verification." />}{selected && <div className="fixed inset-0 z-50 grid place-items-center bg-ink/45 p-5" role="dialog" aria-modal="true"><div className="w-full max-w-lg rounded-2xl bg-card p-6 shadow-2xl"><div className="flex items-start justify-between"><div><p className="font-mono text-[10px] uppercase tracking-widest text-coral">Private review</p><h2 className="mt-2 font-display text-2xl font-bold">{selected.itemName}</h2></div><button onClick={() => setSelected(null)} aria-label="Close review" data-testid="button-close-claim"><X /></button></div><div className="mt-6 rounded-xl bg-mist p-4 text-sm"><p className="font-bold">Claim by {selected.claimantName}</p><p className="mt-1 text-ink-muted">Confidence score: {selected.confidence}%</p><p className="mt-3 leading-6 text-ink-muted">Compare their private ownership details with what you remember before choosing an outcome.</p></div><div className="mt-6 grid gap-2 sm:grid-cols-2"><Button variant="quiet" onClick={() => change(selected, 'manual_review')} data-testid="button-claim-manual-review">Need more review</Button><Button variant="danger" onClick={() => change(selected, 'rejected')} data-testid="button-claim-reject">Reject claim</Button><Button variant="primary" className="sm:col-span-2" onClick={() => change(selected, 'approved')} data-testid="button-claim-approve"><Check size={16} /> Approve ownership</Button></div></div></div>}</>;
}

function NotificationsPage() {
  const query = useListNotifications();
  const mark = useMarkNotificationRead();
  const notifications = query.data || [];
  return <><PageHeader eyebrow="Your feed" title="Notifications" body="Updates about reports, matches, and safe handovers." />{query.isLoading ? <LoadingRows /> : query.isError ? <ErrorState retry={() => query.refetch()} /> : notifications.length ? <div className="max-w-3xl divide-y divide-line rounded-2xl border border-line bg-card">{notifications.map((notice) => <button key={notice.id} onClick={() => !notice.isRead && mark.mutate({ id: notice.id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListNotificationsQueryKey() }) })} className={`flex w-full gap-4 p-5 text-left transition hover:bg-mist ${!notice.isRead ? 'bg-lumen/10' : ''}`} data-testid={`button-notification-${notice.id}`}><span className={`mt-1 grid h-9 w-9 shrink-0 place-items-center rounded-xl ${notice.isRead ? 'bg-mist text-ink-muted' : 'bg-lumen text-ink'}`}><Bell size={16} /></span><span className="min-w-0 flex-1"><span className="flex items-start justify-between gap-3"><span className="font-bold text-ink">{notice.title}</span>{!notice.isRead && <span className="mt-1 h-2 w-2 shrink-0 rounded-full bg-coral" />}</span><span className="mt-1 block text-sm leading-6 text-ink-muted">{notice.message}</span><span className="mt-2 block font-mono text-[10px] text-ink-muted">{notice.createdAt}</span></span></button>)}</div> : <EmptyState icon={Bell} title="You’re all caught up" body="New activity from your reports and claims will show here." />}</>;
}

function MessagesPage() {
  const query = useListMessages();
  const send = useSendMessage();
  const [thread, setThread] = useState('');
  const [body, setBody] = useState('');
  const messages = query.data || [];
  const active = messages.find((message) => message.threadId === thread) || messages[0];
  function submit(event: FormEvent) { event.preventDefault(); if (!thread || !body.trim()) return; send.mutate({ data: { threadId: thread, body } }, { onSuccess: () => { setBody(''); queryClient.invalidateQueries({ queryKey: getListMessagesQueryKey() }); } }); }
  return <><PageHeader eyebrow="Private inbox" title="Messages" body="Keep conversations about returns in one secure place. Contact details are never displayed publicly." /><div className="grid min-h-[520px] overflow-hidden rounded-2xl border border-line bg-card lg:grid-cols-[300px_1fr]">{query.isLoading ? <div className="p-5 lg:col-span-2"><LoadingRows /></div> : query.isError ? <div className="p-5 lg:col-span-2"><ErrorState retry={() => query.refetch()} /></div> : messages.length ? <><div className="border-b border-line lg:border-b-0 lg:border-r"><div className="border-b border-line p-4"><div className="flex items-center gap-2 text-sm font-bold"><Inbox size={16} className="text-teal" /> Inbox</div></div><div className="divide-y divide-line">{messages.map((message) => <button key={message.id} onClick={() => setThread(message.threadId)} className={`w-full p-4 text-left hover:bg-mist ${active?.threadId === message.threadId ? 'bg-mist' : ''}`} data-testid={`button-message-thread-${message.threadId}`}><div className="flex items-center justify-between gap-2"><span className="text-sm font-bold">{message.senderName}</span>{message.unread && <span className="h-2 w-2 rounded-full bg-coral" />}</div><p className="mt-1 truncate text-xs text-ink-muted">{message.itemName || 'Campus Pick message'}</p><p className="mt-2 truncate text-xs text-ink-muted">{message.preview}</p></button>)}</div></div><div className="flex flex-col"><div className="border-b border-line p-5"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-full bg-teal font-mono text-xs font-bold text-sand">{active?.senderName?.slice(0, 2).toUpperCase()}</span><div><p className="font-bold">{active?.senderName}</p><p className="text-xs text-ink-muted">{active?.senderRole} · {active?.itemName || 'Campus Pick'}</p></div></div></div><div className="flex-1 p-5"><div className="max-w-xl rounded-2xl rounded-tl-sm bg-mist p-4 text-sm leading-6 text-ink">{active?.body || active?.preview}</div><p className="mt-2 font-mono text-[10px] text-ink-muted">{active?.createdAt}</p></div><form onSubmit={submit} className="border-t border-line p-4"><div className="flex gap-2"><input value={body} onChange={(e) => setBody(e.target.value)} placeholder="Write a private reply..." className="h-11 min-w-0 flex-1 rounded-xl border border-line bg-background px-3.5 text-sm outline-none focus:border-teal" data-testid="input-message-body" /><Button type="submit" disabled={send.isPending} aria-label="Send message" data-testid="button-send-message"><Send size={16} /><span className="hidden sm:inline">Send</span></Button></div></form></div></> : <div className="lg:col-span-2"><EmptyState icon={MessageSquare} title="No messages yet" body="When a conversation starts around a report or handover, it will appear here." /></div>}</div></>;
}

function SecurityPage() {
  const query = useGetSecurityQueue();
  const verify = useVerifyHandover();
  const [codes, setCodes] = useState<Record<number, string>>({});
  const queue = query.data;
  function submit(id: number) { verify.mutate({ id, data: { code: codes[id] || '' } }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getGetSecurityQueueQueryKey() }) }); }
  return <><PageHeader eyebrow="Security desk" title="Handover queue" body="Verify ownership in person, then close the loop with a one-time handover code." />{query.isLoading ? <LoadingRows /> : query.isError || !queue ? <ErrorState retry={() => query.refetch()} /> : <div className="grid gap-6 xl:grid-cols-[1fr_.7fr]"><section><div className="mb-4 flex items-center justify-between"><h2 className="font-display text-xl font-bold">Upcoming handovers</h2><StatusPill tone="blue">{queue.handovers.length} scheduled</StatusPill></div>{queue.handovers.length ? <div className="space-y-3">{queue.handovers.map((handover) => <div key={handover.id} className="rounded-2xl border border-line bg-card p-5" data-testid={`row-handover-${handover.id}`}><div className="flex items-start justify-between gap-4"><div><h3 className="font-display text-lg font-bold">{handover.itemName}</h3><p className="mt-1 text-sm text-ink-muted">{handover.scheduledFor} · {handover.location}</p></div><StatusPill tone={handover.status === 'completed' ? 'green' : 'amber'}>{handover.status}</StatusPill></div>{handover.status !== 'completed' && <div className="mt-5 flex gap-2"><input value={codes[handover.id] || ''} onChange={(e) => setCodes((prev) => ({ ...prev, [handover.id]: e.target.value }))} placeholder="Enter handover code" className="h-10 flex-1 rounded-xl border border-line bg-background px-3 text-sm outline-none focus:border-teal" data-testid={`input-handover-code-${handover.id}`} /><Button disabled={verify.isPending || !(codes[handover.id] || '').trim()} onClick={() => submit(handover.id)} data-testid={`button-verify-handover-${handover.id}`}><Check size={15} /> Verify</Button></div>}</div>)}</div> : <EmptyState icon={ShieldCheck} title="No handovers scheduled" body="Approved claims ready for in-person collection will show here." />}</section><section className="rounded-2xl bg-ink p-6 text-sand"><div className="flex items-center justify-between"><p className="font-mono text-xs uppercase tracking-widest text-lumen">Stored on campus</p><PackageCheck size={19} className="text-lumen" /></div><p className="mt-8 font-display text-6xl font-bold">{queue.storedCount}</p><p className="mt-2 text-sm text-sand/60">items currently logged with the security desk</p><div className="mt-8 border-t border-white/10 pt-5 text-sm leading-6 text-sand/70"><p className="font-bold text-sand">Handover reminder</p><p className="mt-1">Always check the claimant’s private details before releasing an item.</p></div></section></div>}</>;
}

function AdminPage() {
  const query = useGetAdminSummary();
  const summary = query.data;
  return <><PageHeader eyebrow="Operations" title="Admin summary" body="A high-level view of campus recovery activity and moderation signals." />{query.isLoading ? <LoadingRows /> : query.isError || !summary ? <ErrorState retry={() => query.refetch()} /> : <><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[['Total users', summary.totalUsers], ['Lost reports', summary.lostReports], ['Found reports', summary.foundReports], ['Items returned', summary.returnedItems]].map(([label, value]) => <div key={String(label)} className="rounded-2xl border border-line bg-card p-5"><p className="text-sm text-ink-muted">{label}</p><p className="mt-4 font-display text-4xl font-bold">{value}</p></div>)}</div><div className="mt-6 grid gap-6 xl:grid-cols-[1.2fr_.8fr]"><section className="rounded-2xl border border-line bg-card p-6"><div className="flex items-center justify-between"><div><h2 className="font-display text-xl font-bold">Reports this week</h2><p className="mt-1 text-sm text-ink-muted">Lost vs found, by day</p></div><BarLegend /></div><div className="mt-8 flex h-56 items-end justify-between gap-3">{summary.weeklyReports.map((day) => { const max = Math.max(day.lost, day.found, 1); return <div key={day.day} className="flex flex-1 flex-col items-center gap-2"><div className="flex h-44 w-full items-end justify-center gap-1.5"><div className="w-3 rounded-t-md bg-coral/75" style={{ height: `${Math.max(8, day.lost / max * 100)}%` }} /><div className="w-3 rounded-t-md bg-teal" style={{ height: `${Math.max(8, day.found / max * 100)}%` }} /></div><span className="font-mono text-[10px] text-ink-muted">{day.day}</span></div>})}</div></section><section className="rounded-2xl border border-line bg-card p-6"><h2 className="font-display text-xl font-bold">Moderation pulse</h2><div className="mt-5 space-y-4"><div className="flex items-center justify-between border-b border-line pb-4"><span className="text-sm text-ink-muted">Matched items</span><span className="font-mono font-bold text-teal">{summary.matchedItems}</span></div><div className="flex items-center justify-between border-b border-line pb-4"><span className="text-sm text-ink-muted">Claims in review</span><span className="font-mono font-bold">{summary.claims}</span></div><div className="flex items-center justify-between"><span className="text-sm text-ink-muted">Suspicious reports</span><span className="font-mono font-bold text-coral">{summary.suspiciousReports}</span></div></div><Link href="/claims" className="mt-8 flex items-center justify-between rounded-xl bg-mist px-4 py-3 text-sm font-bold text-ink hover:bg-mist-deep" data-testid="link-admin-review-claims">Review claims <ArrowRight size={16} /></Link></section></div></>}</>;
}

function BarLegend() { return <div className="flex gap-4 text-[11px] text-ink-muted"><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-coral/75" /> Lost</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-teal" /> Found</span></div>; }

function ProfilePage() {
  return <><PageHeader eyebrow="Account" title="Your profile" body="Keep your campus identity and notification preferences up to date." action={<Button variant="outline" onClick={() => alert('Profile editing will be available through your secure account settings.')} data-testid="button-edit-profile"><PencilLine size={16} /> Edit profile</Button>} /><div className="grid gap-6 lg:grid-cols-[.7fr_1.3fr]"><section className="rounded-2xl bg-ink p-7 text-sand"><span className="grid h-16 w-16 place-items-center rounded-full bg-lumen font-mono text-xl font-bold text-ink">JL</span><h2 className="mt-5 font-display text-2xl font-bold">Jordan Lee</h2><p className="mt-1 text-sm text-sand/60">Student · Class of 2026</p><div className="mt-8 border-t border-white/10 pt-5 text-sm"><p className="text-sand/50">Campus email</p><p className="mt-1 font-bold">jordan.lee@campus.edu</p></div></section><section className="rounded-2xl border border-line bg-card p-6"><h2 className="font-display text-xl font-bold">Account details</h2><div className="mt-6 grid gap-5 sm:grid-cols-2"><Field label="First name" name="firstName" value="Jordan" /><Field label="Last name" name="lastName" value="Lee" /><Field label="Campus email" name="email" type="email" value="jordan.lee@campus.edu" /><Field label="Preferred location" name="preferredLocation" value="North campus" /></div><div className="mt-8 border-t border-line pt-6"><h3 className="font-bold">Privacy and notifications</h3><label className="mt-4 flex items-center justify-between gap-4 rounded-xl bg-mist p-4 text-sm"><span><span className="block font-bold">Match alerts</span><span className="mt-1 block text-xs text-ink-muted">Notify me when reports look connected.</span></span><input type="checkbox" defaultChecked className="h-5 w-5 accent-teal" data-testid="checkbox-match-alerts" /></label><label className="mt-3 flex items-center justify-between gap-4 rounded-xl bg-mist p-4 text-sm"><span><span className="block font-bold">Handover updates</span><span className="mt-1 block text-xs text-ink-muted">Keep me posted about claim progress.</span></span><input type="checkbox" defaultChecked className="h-5 w-5 accent-teal" data-testid="checkbox-handover-updates" /></label></div></section></div></>;
}

function ClerkAuthPage({ mode }: { mode: 'sign-in' | 'sign-up' }) {
  const Component = mode === 'sign-in' ? SignIn : SignUp;
  return <div className="flex min-h-[100dvh] items-center justify-center bg-ink px-4 py-8"><div className="w-full max-w-[440px]"><div className="mb-5 flex justify-center"><Logo inverse /></div><Component routing="path" path={`${basePath}/${mode}`} signInUrl={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`} /></div></div>;
}

function ItemDetailPage() {
  const [, params] = useRoute('/find/:id');
  const itemId = Number(params?.id || 0);
  const query = useGetItem(itemId, { query: { queryKey: ['/api/items', itemId], enabled: !!itemId } });
  if (!itemId) return <Redirect to="/find" />;
  if (query.isLoading) return <LoadingRows />;
  if (query.isError || !query.data) return <ErrorState retry={() => query.refetch()} />;
  const item = query.data;
  return <div className="mx-auto max-w-3xl"><Link href="/find" className="mb-6 inline-flex items-center gap-2 text-sm font-bold text-ink-muted hover:text-teal" data-testid="link-back-find">← Back to directory</Link><article className="overflow-hidden rounded-2xl border border-line bg-card"><div className="flex h-56 items-center justify-center bg-mist text-teal">{item.imageUrl ? <img src={item.imageUrl} alt={item.itemName} className="h-full w-full object-cover" /> : <PackageCheck size={52} />}</div><div className="p-6 md:p-8"><div className="flex flex-wrap items-center gap-2"><StatusPill tone={item.type === 'lost' ? 'red' : 'green'}>{item.type}</StatusPill><span className="font-mono text-xs text-ink-muted">{item.reportId}</span></div><h1 className="mt-4 font-display text-3xl font-bold">{item.itemName}</h1><p className="mt-3 text-ink-muted">{item.description}</p><div className="mt-7 grid gap-4 border-y border-line py-6 sm:grid-cols-2"><div><p className="text-xs text-ink-muted">Location</p><p className="mt-1 font-bold">{item.location}</p></div><div><p className="text-xs text-ink-muted">Date</p><p className="mt-1 font-bold">{item.eventDate}</p></div><div><p className="text-xs text-ink-muted">Category</p><p className="mt-1 font-bold">{item.category}</p></div><div><p className="text-xs text-ink-muted">Status</p><p className="mt-1 font-bold capitalize">{item.status}</p></div></div>{item.matches?.length ? <div className="mt-7 rounded-2xl border border-lumen/60 bg-lumen/10 p-5"><div className="flex items-start justify-between gap-4"><div><p className="font-mono text-[10px] uppercase tracking-widest text-teal">Explainable match</p><h2 className="mt-2 font-display text-xl font-bold">{item.matches[0].score}% potential match</h2></div><Sparkles className="text-teal" size={22} /></div><p className="mt-2 text-sm leading-6 text-ink-muted">Suggested because of {item.matches[0].reason}. The score is a review aid, not proof of ownership.</p></div> : null}<div className="mt-7"><div className="flex items-center justify-between"><h2 className="font-display text-xl font-bold">Recovery timeline</h2><StatusPill tone={item.status === 'returned' ? 'green' : 'blue'}>{item.status}</StatusPill></div><div className="mt-5 space-y-4">{(item.timeline || []).map((event) => <div key={event.status} className="flex items-start gap-3"><span className={`mt-1 grid h-7 w-7 shrink-0 place-items-center rounded-full ${event.completed ? 'bg-teal text-sand' : 'bg-mist text-ink-muted'}`}>{event.completed ? <Check size={14} /> : <span className="h-2 w-2 rounded-full bg-current" />}</span><div><p className={`text-sm font-bold ${event.completed ? 'text-ink' : 'text-ink-muted'}`}>{event.label}</p><p className="mt-0.5 text-xs text-ink-muted">{event.completed ? event.date || 'Completed' : 'Next checkpoint'}</p></div></div>)}</div></div><div className="mt-7 flex items-center gap-3 rounded-xl bg-mist p-4 text-sm text-ink-muted"><LockKeyhole size={17} className="shrink-0 text-teal" /> Identifying details are hidden to protect the rightful owner.</div><Link href="/claims" className="mt-6 inline-flex rounded-xl bg-teal px-4 py-3 text-sm font-bold text-sand" data-testid="link-start-claim">This might be mine <ArrowRight size={16} /></Link></div></article></div>;
}

function Router() {
  return <ErrorBoundary resetKey={window.location.pathname}><Switch>
    <Route path="/" component={PublicHome} />
    <Route path="/sign-in/*?" component={() => <ClerkAuthPage mode="sign-in" />} />
    <Route path="/sign-up/*?" component={() => <ClerkAuthPage mode="sign-up" />} />
     <Route path="/how-it-works"><HowItWorksPage /></Route>
    <Route path="/find/:id" component={ItemDetailPage} />
    <Route path="/dashboard"><AppShell><DashboardPage /></AppShell></Route>
    <Route path="/find"><AppShell><FindPage /></AppShell></Route>
    <Route path="/report/lost"><AppShell><ReportPage type="lost" /></AppShell></Route>
    <Route path="/report/found"><AppShell><ReportPage type="found" /></AppShell></Route>
    <Route path="/matches"><AppShell><MatchesPage /></AppShell></Route>
    <Route path="/claims"><AppShell><ClaimsPage /></AppShell></Route>
    <Route path="/messages"><AppShell><MessagesPage /></AppShell></Route>
    <Route path="/notifications"><AppShell><NotificationsPage /></AppShell></Route>
    <Route path="/security"><AppShell><SecurityPage /></AppShell></Route>
    <Route path="/admin"><AppShell><AdminPage /></AppShell></Route>
    <Route path="/profile"><AppShell><ProfilePage /></AppShell></Route>
    <Route component={NotFound} />
  </Switch></ErrorBoundary>;
}

function App() {
  if (!clerkPubKey) throw new Error('Missing VITE_CLERK_PUBLISHABLE_KEY for Campus Pick authentication.');
  return <WouterRouter base={basePath}><ClerkProvider publishableKey={clerkPubKey} proxyUrl={clerkProxyUrl} appearance={clerkAppearance} signInUrl={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`} routerPush={(to) => { window.history.pushState({}, '', stripBase(to)); window.dispatchEvent(new PopStateEvent('popstate')); }} routerReplace={(to) => { window.history.replaceState({}, '', stripBase(to)); window.dispatchEvent(new PopStateEvent('popstate')); }}><QueryClientProvider client={queryClient}><TooltipProvider><Router /><Toaster /></TooltipProvider></QueryClientProvider></ClerkProvider></WouterRouter>;
}

export default App;